Index: game.js
===================================================================
--- game.js
+++ game.js
@@ -30,9 +30,9 @@
   const setScreen=(html)=>{screen.innerHTML=html;};
   function intro(){scene='intro';shell.classList.remove('is-playing');controls.classList.remove('active');setScreen(`<article class="panel"><div class="eyebrow">A FICTIONAL FLIGHT-SAFETY STORY</div><h1>Hold the line.<br>Bring them home.</h1><p>A respectful, alternate-history action game inspired by courage and cooperation. Face a crisis in a fictionalized cabin and help every passenger reach safety.</p><button class="primary" id="start">BEGIN THE STORY&nbsp; →</button><div class="key-hint">MOVE&nbsp; A / D OR ← / → &nbsp;·&nbsp; JUMP&nbsp; W / ↑ &nbsp;·&nbsp; JAB&nbsp; J &nbsp;·&nbsp; KICK&nbsp; K &nbsp;·&nbsp; GUARD&nbsp; SPACE &nbsp;·&nbsp; RALLY&nbsp; Q</div></article>`);document.getElementById('start').onclick=()=>briefing(0);}
   function briefing(index){stageIndex=index;scene='brief';shell.classList.remove('is-playing');controls.classList.remove('active');const s=stage();const mission=s.mission||index-(s.chapter===1?0:4)+1;const total=s.waves.reduce((sum,n)=>sum+waveSize(n),0);setScreen(`<article class="panel"><div class="eyebrow">CHAPTER ${s.chapter} · MISSION ${mission} OF ${s.chapter===1?4:5}&nbsp; · &nbsp;${s.sub}</div><h1>${s.name}</h1><p>${s.lesson}<br><span style="color:${s.color}">${s.place}.</span>${s.boss&&s.chapter===2?'<br><br><strong>Final encounter: a fictional local leader.</strong> The scene resolves peacefully; it does not depict a real person or event.':s.boss?'<br><br><strong>Boss encounter: two phases. Each phase has a large health bar.</strong>':''}<br><br><strong>${s.waves.length} waves · ${total} opponents</strong><br>The opposing group is al Qaeda. RALLY (Q) restores health and interrupts nearby threats; it recharges in 30 seconds. Jump with W or ↑ to avoid attacks.</p><label class="difficulty-picker" for="difficulty"><span>DIFFICULTY</span><select id="difficulty"><option value="easy" ${difficulty==='easy'?'selected':''}>Easy</option><option value="normal" ${difficulty==='normal'?'selected':''}>Normal</option><option value="hard" ${difficulty==='hard'?'selected':''}>Hard</option></select></label><div class="difficulty-note" id="difficultyNote">${settings().description}</div><button class="primary" id="go">TAKE YOUR POSITION&nbsp; →</button><div class="key-hint">A respectful retelling: no graphic imagery, names, or reenactment of real-world harm.</div></article>`);document.getElementById('difficulty').onchange=e=>{difficulty=e.target.value;document.getElementById('difficultyNote').textContent=settings().description;const count=s.waves.reduce((sum,n)=>sum+waveSize(n),0);document.querySelector('.panel p strong').textContent=`${s.waves.length} waves · ${count} opponents`};document.getElementById('go').onclick=startStage;}
   function bossPhase(){const s=stage();if(!s.boss)return 0;if(s.bossPhases)return waveIndex>=s.waves.length-s.bossPhases?waveIndex-(s.waves.length-s.bossPhases)+1:0;return waveIndex===s.waves.length-1?1:0;}
-  function spawnWave(){enemies=[];const s=stage(),count=waveSize(s.waves[waveIndex]),phase=bossPhase();for(let i=0;i<count;i++){const isBoss=phase>0&&i===count-1;const hp=isBoss?(s.bossHealth?.[phase-1]||260):165;enemies.push({x:620+i*92,y:394,hp,max:hp,attack:(1.2+i*.65)/settings().attackRate,attackAnim:0,attackHit:false,guard:0,stun:0,facing:-1,walk:i*2,alive:true,boss:isBoss,bossPhase:phase});}wavePause=0;say(phase?`FINAL ENCOUNTER · PHASE ${phase} OF ${s.bossPhases||1}`:`Wave ${waveIndex+1} of ${s.waves.length} — stay together!`);}
+  function spawnWave(){enemies=[];const s=stage(),count=waveSize(s.waves[waveIndex]),phase=bossPhase();for(let i=0;i<count;i++){const isBoss=phase>0&&i===count-1;const hp=isBoss?(s.bossHealth?.[phase-1]||260):165;enemies.push({x:620+i*44,y:394,hp,max:hp,attack:(1.2+i*.65)/settings().attackRate,attackAnim:0,attackHit:false,guard:0,stun:0,facing:-1,walk:i*2,alive:true,boss:isBoss,bossPhase:phase});}wavePause=0;say(phase?`FINAL ENCOUNTER · PHASE ${phase} OF ${s.bossPhases||1}`:`Wave ${waveIndex+1} of ${s.waves.length} — stay together!`);}
   function startStage(){scene='play';shell.classList.add('is-playing');controls.classList.add('active');screen.innerHTML='';elapsed=0;clock=stage().time;message='';messageTimer=0;waveIndex=0;wavePause=0;player={x:250,y:394,hp:260,max:260,attack:0,attackDuration:.28,guard:0,stun:0,facing:1,walk:0,jumpHeight:0,jumpVelocity:0,specialCooldown:0};keys={};lastAction=0;spawnWave();lastTime=performance.now();}
   function victory(){scene='win';controls.classList.remove('active');shell.classList.remove('is-playing');const chapterFinal=stage().boss&&stage().chapter===2;const chapterOneFinal=stage().boss&&stage().chapter===1;setScreen(`<article class="panel"><div class="eyebrow">${chapterFinal?'CHAPTER 2 COMPLETE':chapterOneFinal?'CHAPTER 1 COMPLETE':'MISSION COMPLETE'}</div><h1>${chapterFinal?'The peaceful resolution is complete.':'Everyone made it.'}</h1><p>${chapterFinal?'The fictional local leader has agreed to stand down. Everyone moves toward safety.':chapterOneFinal?'Both boss phases are defeated. The cabin is safe, and the story continues in Chapter 2.':'Because people stood together, the emergency ended with everyone safe. Pause for a breath, then continue the story.'}</p>${stageIndex<stages.length-1?'<button class="primary" id="next">CONTINUE&nbsp; →</button>':'<button class="primary" id="finish">FINISH THE STORY</button>'}<div class="key-hint">Courage is a team effort. Remembering the lives forever changed.</div></article>`);const b=document.getElementById(stageIndex<stages.length-1?'next':'finish');b.onclick=()=>stageIndex<stages.length-1?briefing(stageIndex+1):credits();}
   function credits(){scene='credits';setScreen(`<article class="panel"><div class="eyebrow">IN REMEMBRANCE</div><h1>We remember.</h1><p>Those lost. Those who survived. The families, helpers, and communities changed forever.<br><br>This fictional game is about cooperation and getting people to safety—not recreating the events of September 11.</p><button class="primary" id="again">PLAY AGAIN</button></article>`);document.getElementById('again').onclick=intro;}
   function lose(){scene='retry';controls.classList.remove('active');shell.classList.remove('is-playing');setScreen(`<article class="panel"><div class="eyebrow">TAKE A BREATH</div><h1>Try another approach.</h1><p>Guard to weather an attack, then strike while the other side recovers. You can do this.</p><button class="primary" id="retry">TRY AGAIN&nbsp; ↻</button><button class="secondary" id="back">CHAPTERS</button></article>`);document.getElementById('retry').onclick=startStage;document.getElementById('back').onclick=()=>briefing(stageIndex);}
